(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzs-sj-prepa-med-j7-ide3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzs-sj-prepa-med-j7-ide3\",\n \"titre\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J7_Medecine_IDE3_corrige_explique.pdf\",\n   \"sha256\": \"f069fa4fa8155b745403186fd6d117e4af09fee1d55e080341592b827a1839f0\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Médecine · Prépa D.E J7 (IDE3)\",\n     \"slug\": \"prepa-med-j7-ide3\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Médecine\",\n     \"source\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paludisme grave se définit comme étant un cas de paludisme avec des formes asexuées de Plasmodium falciparum et la présence d'un ou plusieurs signes cliniques ou biologiques\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"C'est mot pour mot la définition du cours : paludisme grave = formes asexuées de P. falciparum + au moins un signe clinique ou biologique de gravité (coma, convulsions répétées, anémie sévère, hypoglycémie…).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 4-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le paludisme, la transmission directe du germe de la femme enceinte infectée à son enfant par voie transplacentaire ou par transfusion sanguine n'est pas le seul cas de contamination interhumaine\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours dit l'inverse : « il existe un seul cas de contamination interhumaine directe », la femme enceinte infectée qui contamine son enfant par voie transplacentaire ou par transfusion sanguine. L'affirmation « n'est pas le seul cas » est donc fausse.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 3 Contamination\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque la femme enceinte est sous prophylaxie antianémique avec l'acide folique + fer, on suspendra le traitement antianémique et on le reprendra 15 j après la prise de SP\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Règle du TPI : si la femme enceinte est sous acide folique + fer, on suspend le traitement antianémique et on le reprend 15 jours après la prise de SP.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 5-2-1-1 ; Cours de pathologies tropicales L1 (INFAS Daloa), § 8-1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On appelle pied diabétique toute infection, ulcération ou destruction des tissus profonds du pied associée à une neuropathie et/ou une artériopathie périphérique des membres inférieurs chez le diabétique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Définition classique du pied diabétique : toute infection, ulcération ou destruction des tissus profonds du pied, associée à une neuropathie et/ou une artériopathie des membres inférieurs chez le diabétique.\\n\\nSource : Définition générale ; le cours IDE 2 traite l'AOMI (facteurs : tabac, diabète) mais pas cette définition (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Schistosoma mansoni est responsable d'une bilharziose urinaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"S. mansoni donne la bilharziose intestinale et hépatosplénique (selles glaireuses, gros foie, grosse rate). La bilharziose urinaire (hématurie terminale) est due à S. haematobium.\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Bilharzioses, § 2-3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'amibiase est une maladie strictement humaine due à un protozoaire rhizopode appelé Entamoeba histolytica\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Entamoeba histolytica est un protozoaire ; le cours précise que l'homme est l'unique réservoir du parasite, d'où une maladie strictement humaine.\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Amibiase, § II\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le tétanos, le trismus désigne une contracture des muscles masticateurs, bloquant l'ouverture de la bouche. Ce signe s'observe à partir de la phase d'état\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le trismus apparaît dès la phase d'invasion (environ 48 h) : c'est le signe de début. Il persiste ensuite à la phase d'état. Dire qu'il « s'observe à partir de la phase d'état » est donc faux.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Tétanos, § 2.1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la crise du tétanos, l'opisthotonos est décrit par le rachis fixé en hyperextension avec tête rejetée en arrière et une hyperlordose lombaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À la phase d'état, « le rachis est fixé en hyperextension avec tête rejetée en arrière, hyperlordose lombaire (opisthotonos) ».\\n\\nSource : Cours de maladies infectieuses et parasitaires, Tétanos, § 2.1 phase d'état\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection à VIH a un profil épidémiologique qui touche plus les enfants\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'infection à VIH touche surtout les adultes jeunes sexuellement actifs (voie sexuelle = mode de transmission le plus courant) ; les enfants sont touchés surtout par transmission mère-enfant.\\n\\nSource : (explication hors cours du projet ; Documents de révision L3 Médecine, VIH, QCD 34 sur la voie sexuelle)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le terme « OEV » s'applique à tout âge allant de 9 à 21 ans\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"OEV = orphelins et enfants rendus vulnérables du fait du VIH ; la tranche d'âge retenue par les programmes est de 0 à 17 ans, et non 9 à 21 ans.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la bilharziose, chez l'homme, les œufs contenant des miracidiums sont éliminés dans l'eau par les excréments ou les urines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les œufs sont rejetés avec les excrétas (urines ou selles) ; dans l'eau douce, ils éclosent et libèrent le miracidium, larve ciliée qui va infester le mollusque.\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Bilharzioses, § 1-3 et 4-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le soin du mal perforant plantaire consiste en un lavage chirurgical de la plaie jusqu'à l'os et à l'articulation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le mal perforant plantaire impose un parage chirurgical de la plaie (excision des tissus nécrosés et de l'hyperkératose jusqu'en tissu sain, éventuellement jusqu'à l'os atteint), associé à la mise en décharge du pied.\\n\\nSource : (explication hors cours du projet ; le cours cite le mal perforant plantaire comme complication de la lèpre)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'envenimation neurotoxique est le fait du cobra non cracheur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'envenimation neurotoxique (troubles sensoriels, ptosis, dysphagie, détresse respiratoire) est le fait des Elapidae (cobras non cracheurs, mambas). Le cobra cracheur, lui, provoque surtout une atteinte oculaire (kérato-conjonctivite).\\n\\nSource : Envenimations – Traitement (diaporama), diapo « Envenimation neurotoxique » ; Cours de pathologies tropicales L1 (INFAS Daloa), Morsures de serpents § VI\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les venins de serpents ont un double mécanisme d'action : l'immobilisation rapide de la proie et la digestion complète\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours dit : « double mécanisme d'action : l'immobilisation rapide de la proie et la prédigestion ». Le mot « digestion complète » rend la phrase fausse (elle figure telle quelle comme item « Faux » dans l'exercice du cours).\\n\\nSource : Envenimations – Traitement (diaporama), Composition des venins ; Cours de venimologie générale, Exercice 3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la gradation des troubles neurologiques, le grade 2 est caractérisé par « détresse respiratoire, communication impossible »\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans le tableau de gradation, « détresse respiratoire, communication impossible » correspond au grade 4. Le grade 2 neurologique = sueurs et salive abondantes, vomissements, myosis.\\n\\nSource : Cours de venimologie générale, Tableau II p. 25\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'agent pathogène de la syphilis est le Treponema pallidum\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La syphilis vénérienne est due au tréponème pâle, Treponema pallidum.\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Tréponématoses – Syphilis, § I\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez celle qui correspond à la méthode de diagnostic biologique de la PCR : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"a- Méthode mixte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"b- Méthode indirecte\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"c- Méthode directe\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"d- Dry Blood Spot (DBS)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. b- Méthode indirecte\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La PCR détecte le génome de l'agent (ADN/ARN) : c'est une méthode directe. Le cours la place parmi les examens de mise en évidence du germe (paludisme, typhoïde, choléra).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme § 4-3 et Fièvre typhoïde § III\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la fièvre typhoïde, les symptômes résumés sous le vocable CIVET s'observent à la phase : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A incubation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B invasion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C d'état\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D des complications\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B invasion\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"CIVET (Céphalées, Insomnie, Vertiges, Épistaxis, Température ascendante) résume la phase d'invasion, c'est-à-dire le 1er septénaire.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § 2.2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fièvre typhoïde évolue généralement en… : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A Un septénaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B Deux septénaires\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C Trois septénaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D Quatre septénaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C Trois septénaires\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Évolution en trois septénaires : 1er = invasion, 2e = phase d'état, 3e = complications.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § 2.2 à 2.4\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la fièvre typhoïde, la diarrhée est caractérisée par : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A des selles liquides, fétides, d'aspect jus de papaye\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B une diarrhée afécale, glaireuse et mucopurulente, parfois sanglante\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C des selles abondantes, aqueuses, afécales, en jet, avec un aspect riziforme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D selles pâteuses ou liquides, non sanglantes, température normale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A des selles liquides, fétides, d'aspect jus de papaye\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au 2e septénaire, la diarrhée typhique est faite de selles liquides, fétides, d'aspect jus de papaye. B = syndrome dysentérique, C = choléra (eau de riz).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Fièvre typhoïde, § 2.3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La splénomégalie palustre hyperactive se définit par : cochez l'intrus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A Présence permanente d'une grosse rate sans fièvre et avec pancytopénie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B Syndrome inflammatoire (accélération de la vitesse de sédimentation)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C Sérologie du paludisme fortement positive mais parasitémie faible ou nulle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D Une hépatomégalie associée à une hémoglobinurie macroscopique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E Absence de signe d'hypertension portale, d'hémopathie ou de tumeur de la rate\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D Une hépatomégalie associée à une hémoglobinurie macroscopique\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La SPH se définit par : grosse rate permanente sans fièvre avec pancytopénie, VS accélérée, sérologie fortement positive avec parasitémie faible ou nulle, absence d'HTP/hémopathie/tumeur. L'hépatomégalie avec hémoglobinurie macroscopique n'en fait pas partie (l'hémoglobinurie est un signe de paludisme grave).\\n\\nSource : Cours de maladies infectieuses et parasitaires, Paludisme, § 4-4\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque l'ascaridiose est symptomatique, elle se déroule en 2 phases : lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A La phase d'incubation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B La phase d'invasion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C La phase d'état\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D La phase de complications\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E La phase des séquelles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B La phase d'invasion ; C. C La phase d'état\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"L'ascaridiose symptomatique se manifeste d'abord par la migration larvaire (phase d'invasion : syndrome de Löffler pulmonaire), puis par la présence des vers adultes dans l'intestin (phase d'état : troubles digestifs).\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Ascaridiose, § 2 Manifestations cliniques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les 4 principaux symptômes en rhumatologie sont : cochez les deux symptômes non fondamentaux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A la douleur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B la claudication\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C l'arthrose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D l'instabilité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E la scoliose\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F la raideur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C l'arthrose ; E. E la scoliose\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Les quatre symptômes fondamentaux en rhumatologie sont la douleur, la raideur, la claudication (boiterie) et l'instabilité. L'arthrose est une maladie et la scoliose une déformation : ce ne sont pas des symptômes.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome dysentérique comprend les caractéristiques suivantes sauf une. Laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"B une diarrhée afécale, glaireuse et mucopurulente, parfois sanglante\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"des douleurs abdominales violentes avec épreintes, ténesmes et faux besoins\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C Des vomissements incoercibles et fréquents\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D une altération de l'état général, de la fièvre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C Des vomissements incoercibles et fréquents\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le syndrome dysentérique associe selles glairo-sanglantes afécales, douleurs avec épreintes et ténesmes, fièvre et altération de l'état général. Les vomissements incoercibles n'en sont pas une caractéristique. Remarque : L'option « des douleurs abdominales violentes… » n'a pas de lettre dans le sujet.\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Syndromes dysentériques et Amibiase\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La présence des glossines dans l'environnement dépend de quatre facteurs : cochez les deux intrus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A la chaleur (température entre 25 et 30 °C)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B l'humidité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C la sècheresse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D l'ombrage\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E la présence de cours d'eau (fleuve, rivière, marécage)\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F la présence de nourriture\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C la sècheresse ; E. E la présence de cours d'eau (fleuve, rivière, marécage)\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Les quatre facteurs de présence des glossines sont la chaleur (25-30 °C), l'humidité, l'ombrage et la présence de nourriture. La sècheresse et la présence de cours d'eau sont les intrus retenus. Remarque : Dans la question proche du recueil de révision, les intrus proposés sont « obscurité » et « sècheresse » ; les cours d'eau y sont cités comme habitat des glossines (QCM 9).\\n\\nSource : Documents de révision L3 Médecine, Trypanosomiase humaine africaine, QCM 10\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le stade primaire de la syphilis est caractérisé par : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A plaques muqueuses buccales à la face interne des lèvres et des joues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B lésions cutanées à type de syphilides papuleuses circinées, sèches ou psoriasiformes, siégeant dans les régions humides (creux axillaires)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C il n'y a pas de chancre d'inoculation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C il n'y a pas de chancre d'inoculation\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le stade primaire est caractérisé par le chancre : ulcération génitale unique, superficielle, indolore, propre, à base indurée, avec adénopathie inguinale. A et B relèvent de la syphilis secondaire.\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Syphilis, § 2-1 et 2-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Non traitée, la lèpre indéterminée évolue différemment selon la résistance du sujet vers : cochez les deux bonnes propositions\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A La lèpre « tuberculoïde » contagieuse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B La lèpre « lépromateuse » contagieuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C La lèpre « tuberculoïde » non contagieuse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D La lèpre « lépromateuse » non contagieuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B La lèpre « lépromateuse » contagieuse ; C. C La lèpre « tuberculoïde » non contagieuse\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Selon la résistance du sujet : forte résistance → lèpre tuberculoïde (peu de bacilles, non contagieuse) ; faible résistance → lèpre lépromateuse (multibacillaire, contagieuse).\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), La lèpre, § 3-2 et 3-3\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pouvoir pathogène des germes des agents infectieux dépend de plusieurs facteurs qui sont : cochez les deux propositions fausses\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A La virulence\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B La toxicité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C Le pouvoir anticorps\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D La sécrétion d'enzyme\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E La phagocytose\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F Le pouvoir antigénique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C Le pouvoir anticorps ; E. E La phagocytose\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Les quatre facteurs du pouvoir pathogène sont : virulence, toxicité, sécrétion d'enzyme, pouvoir antigénique. « Pouvoir anticorps » et « phagocytose » (mécanisme de défense de l'hôte) sont faux.\\n\\nSource : Cours de maladies infectieuses et parasitaires, Généralités, § 2.2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La toilette quotidienne des pieds diabétiques se fait avec de l'eau à : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A 34° - 36 °C bain froid\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B 36° - 37 °C bain normal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C 39° - 45 °C au bain-marie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B 36° - 37 °C bain normal\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La toilette quotidienne des pieds du diabétique se fait à l'eau tiède (environ 37 °C, vérifiée au thermomètre ou au coude) car la neuropathie supprime la sensation de brûlure ; l'eau trop chaude expose aux brûlures.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les deux grands facteurs favorisant l'apparition du pied diabétique sont constitués par l'atteinte des : cochez les deux bonnes propositions\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A artères\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B tissus mous\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C nerfs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D veines\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E vaisseaux lymphatiques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A artères ; C. C nerfs\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les deux grands mécanismes du pied diabétique sont la neuropathie (atteinte des nerfs) et l'artériopathie (atteinte des artères) ; l'infection vient compliquer.\\n\\nSource : Cohérent avec la Q4 ; Cours de médecine IDE 2 (INFAS, actualisé 2020), AOMI (facteurs de risque : diabète) (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'envenimation causée par une vipère peut entraîner : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"hypersalivation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"phlyctène\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"acouphène\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. phlyctène\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les vipères donnent un syndrome vipérin : œdème, saignements, ecchymoses, phlyctènes (grade 3 hémorragique). Hypersalivation et acouphènes évoquent plutôt une envenimation neurotoxique (élapidés).\\n\\nSource : Cours de venimologie générale, Tableau II ; Envenimations – Traitement (diaporama), diapo « Phlyctènes »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de morsure de serpent, il est conseillé : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Poser un garrot\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Inciser la plaie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"allonger la victime, la mettre au repos\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. allonger la victime, la mettre au repos\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Rôle infirmier : allonger le sujet mordu et le laisser au repos. Le garrot est déconseillé et l'incision est à proscrire.\\n\\nSource : Cours de pathologies tropicales L1 (INFAS Daloa), Morsures de serpents, § 5-2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un élément de la gradation des troubles hémorragiques est : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"détresse respiratoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"purpura\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"anesthésie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. purpura\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Gradation des troubles hémorragiques : grade 3 = ecchymoses, hématomes, purpura, phlyctènes. La détresse respiratoire et l'anesthésie appartiennent à la gradation neurologique.\\n\\nSource : Envenimations – Traitement (diaporama), Gradation des troubles hémorragiques ; Cours de venimologie générale, Tableau II III- ÉTUDE DE CAS 1 (Q34 à Q37) — L'élève G.G.D, 16 ans, au cours des vacances scolaires, a une aventure sexuelle avec une jeune fille. Le motif de sa consultation dans votre centre est une brûlure mictionnelle accompagnée d'une dysurie et d'une plaie au niveau du pénis.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelles sont les complications possibles encourues par cet élève si sa prise en charge n'est pas faite ? (deux réponses sont bonnes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"imperméabilité tubaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"orchi-épididymite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"cancer précoce des organes atteints\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"rétrécissement de l'urètre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"accouchement prématuré de la partenaire infectée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. orchi-épididymite ; D. rétrécissement de l'urètre\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Chez l'homme, une IST (urétrite) non traitée se complique localement d'orchi-épididymite et de rétrécissement (sténose) de l'urètre. L'imperméabilité tubaire et l'accouchement prématuré concernent la femme.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelles sont les étapes de la bonne prise en charge ? Comme pour tout motif de consultation médicale, elle nécessite 7 étapes : Enregistrement des cas/notification (1) ; Notification au(x) partenaire(s) (2) ; Entretien/conseil (counseling) (3) ; Traitement (4) ; Diagnostic syndromique (5) ; Examen physique (6) ; Accueil et interrogatoire (7). Quel est l'ordre correct ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1) ; (2) ; (3) ; (4) ; (5) ; (6) ; (7)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(1) ; (2) ; (4) ; (5) ; (6) ; (7) ; (3)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1) ; (2) ; (5) ; (6) ; (7) ; (3) ; (4)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(1) ; (2) ; (6) ; (7) ; (3) ; (4) ; (5)\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(7) ; (6) ; (5) ; (4) ; (3) ; (2) ; (1)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. (7) ; (6) ; (5) ; (4) ; (3) ; (2) ; (1)\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"L'ordre logique d'une prise en charge est : accueil et interrogatoire (7) → examen physique (6) → diagnostic syndromique (5) → traitement (4) → counseling (3) → notification au(x) partenaire(s) (2) → enregistrement/notification (1).\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les diagnostics syndromiques ci-dessous, lesquels peuvent s'appliquer dans le cas de G.G.D ? (deux réponses bonnes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Syndrome d'écoulement urétral et/ou anorectal masculin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Syndrome d'écoulement vaginal et/ou anorectal chez la femme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Syndrome de douleurs testiculaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Syndrome d'ulcérations génitales et/ou bubon\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Syndrome de douleurs abdominales basses chez la femme\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Syndrome de végétations vénériennes ou condylomes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Syndrome d'écoulement urétral et/ou anorectal masculin ; D. Syndrome d'ulcérations génitales et/ou bubon\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Brûlure mictionnelle + dysurie = écoulement urétral masculin ; plaie du pénis = ulcération génitale. Les autres syndromes concernent la femme ou ne correspondent pas au tableau.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez les deux qui ne peuvent constituer des conseils à donner à Monsieur G.G.D\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Conseiller à ses partenaires sexuels de voir un professionnel de la santé pour une bonne prise en charge\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ne pas utiliser les mêmes ustensiles de cuisine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Utiliser dorénavant la double protection\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire un dépistage sérologique du VIH et une prise en charge ARV si possible\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"S'auto-stigmatiser\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Ne pas utiliser les mêmes ustensiles de cuisine ; E. S'auto-stigmatiser\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Les conseils pertinents : informer les partenaires, double protection, dépistage VIH. « Ne pas partager les ustensiles de cuisine » n'a pas de sens (pas de transmission par les objets du repas) et « s'auto-stigmatiser » est à combattre.\\n\\nSource : Cours VIH Licence 2 (TARV), chapitre 6 Santé positive, dignité et prévention ; Documents de révision L3 Médecine, VIH QCD 21 (double protection)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Le diagnostic de Sieur T.R retenu par le médecin est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A Infarctus du myocarde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B Crise d'OAP\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C AVC\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D Angine de poitrine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D Angine de poitrine\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Douleur rétrosternale constrictive à l'effort, irradiant à la mâchoire et au bras gauche, brève (1-3 min), cédant à l'arrêt de l'effort et à la trinitrine : c'est l'angine de poitrine (angor d'effort). Remarque : Dans le sujet, l'option est écrite « Agine de poitrine ».\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Angine de poitrine, § 5\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Le médecin vous demande de rappeler une définition correcte de cette pathologie : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A un syndrome douloureux thoracique en rapport avec l'obstruction complète de la lumière d'une ou plusieurs artères coronaires entraînant un déficit en oxygène et une nécrose du myocarde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B inondation brutale des alvéoles pulmonaires et du tissu pulmonaire interstitiel par transsudation de plasma provenant d'une augmentation de la pression capillaire pulmonaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C un syndrome douloureux thoracique en rapport avec une diminution du débit sanguin coronaire entraînant une hypoxie du myocarde liée à un déséquilibre entre les apports et les besoins en oxygène\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C un syndrome douloureux thoracique en rapport avec une diminution du débit sanguin coronaire entraînant une hypoxie du myocarde liée à un déséquilibre entre les apports et les besoins en oxygène\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Définition du cours : « syndrome douloureux thoracique en rapport avec une diminution du débit sanguin coronaire entraînant un besoin en oxygène du myocarde ». A décrit l'infarctus (obstruction complète, nécrose), B l'OAP.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Angine de poitrine, § 1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Les facteurs de risque majeurs de cette affection sont : cochez le facteur qui représente 95 % de risque\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A Tabagisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B HTA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C athérosclérose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D Diabète\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C athérosclérose\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La cause de l'angor est la plaque d'athérome coronaire qui réduit l'apport d'O2 au myocarde ; l'athérosclérose est donc en cause dans la quasi-totalité des cas. Tabac, HTA, diabète sont des facteurs de risque de cette athérosclérose. Remarque : Le chiffre de 95 % ne figure pas dans le cours.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Angine de poitrine, § 2 et 4\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Dans votre rôle d'IDE, vous surveillerez le traitement hygiéno-diététique basé sur : cochez l'intrus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A Régime hyposodé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B Régime hypolipidique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C Sevrage de la consommation d'alcool et du tabac\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D Repos et sédentarité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D Repos et sédentarité\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le traitement hygiéno-diététique associe régime hyposodé, régime hypolipidique et arrêt alcool/tabac. La sédentarité est un facteur de risque : « repos et sédentarité » est l'intrus.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Angine de poitrine, § 4 (facteurs de risque : sédentarité)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Vos initiatives d'éducation thérapeutique seront basées sur : cochez l'intrus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A Expliquer les effets secondaires probables des médicaments\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B Expliquer l'importance du suivi des règles hygiéno-diététiques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C Expliquer au patient que le traitement est à vie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D Expliquer au patient les effets néfastes de ses habitudes de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D Expliquer au patient les effets néfastes de ses habitudes de vie\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'éducation thérapeutique d'un coronarien porte sur les effets des médicaments, le suivi des règles hygiéno-diététiques, le caractère à vie du traitement et les effets néfastes de ses habitudes (tabac, cola). Remarque : Les quatre propositions paraissent toutes relever de l'éducation thérapeutique ; l'option D vise justement le tabac et la cola du patient. La correction nationale de la Prépa DE (les J) retient D comme intrus.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Il vous est demandé de calculer la taille de votre patient qui est : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A 148 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B 146 cm\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C 144 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A 148 cm\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Taille² = poids / IMC = 62 / 28 = 2,214 → taille = √2,214 ≈ 1,488 m, soit 148 cm.\\n\\nSource : Calcul (IMC = poids / taille²)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"L'IMC suggère que le patient : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A est dénutri\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B a un poids normal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C est en surpoids\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D est obèse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C est en surpoids\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"IMC = 28 : entre 25 et 29,9 → surpoids (obésité à partir de 30).\\n\\nSource : (explication hors cours du projet : classification OMS de l'IMC)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"La diurèse du patient indique une : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A anurie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B oligurie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C polyurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D pollakiurie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B oligurie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"555 ml/24 h est une diurèse basse ; la correction nationale de la Prépa DE (les J) retient l'oligurie. Remarque : Le seuil habituel de l'oligurie est < 500 ml/24 h (le cours, au paludisme grave, cite < 400 ml) ; 555 ml est juste au-dessus.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Tenant compte de la symptomatologie de Sieur T.R, vous essayez de formuler un diagnostic infirmier en lien avec un besoin prioritaire non satisfait selon Virginia Henderson. Pour l'accompagnement d'un patient en phase terminale de vie, le médecin a prescrit une perfusion de 1 litre de Ringer lactate en 24 h. Calculer le débit de la perfusion et choisir la réponse exacte parmi les propositions suivantes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A- 14 gouttes/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B- 13 gouttes/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C- 12 gouttes/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A- 14 gouttes/min\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (ml) × 20 / temps (min) = 1 000 × 20 / 1 440 = 13,9 ≈ 14 gouttes/min.\\n\\nSource : Calcul de débit (1 ml = 20 gouttes de soluté)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Le débit de cette perfusion en maintien est de 20 gouttes par minute en 8 h. Indiquez le volume de soluté passé dans ce temps. Cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A- 280 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B- 380 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C- 480 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D- 580 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C- 480 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Volume = débit × temps / 20 = 20 gouttes/min × 480 min / 20 = 480 ml.\\n\\nSource : Calcul de débit (1 ml = 20 gouttes)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Vous êtes de garde à l'EPHD de Toulépleu ; vous recevez avec le médecin Sieur T.R, vendeur et consommateur de noix de cola, avec des signes cliniques dominés par une douleur : circonstances d'apparition : douleur à l'effort qui cède en quelques minutes à l'arrêt de l'effort ; siège rétrosternal ; irradiations typiquement vers la mâchoire inférieure et le bras gauche ; type : constriction, en étau ; durée brève, entre 1 et 3 minutes ; la douleur cesse à l'arrêt de l'effort. Constantes : T° 36,8 °C – Poids 62 kg, IMC estimé à 28 – Pouls 88/min – FR 31 cycles/min – TA 172/101 mmHg (même valeur après plus de trois reprises). Antécédents de tabagisme notoire avec consommation habituelle de noix de cola, haleine fétide et dents ardoisées. Le médecin prescrit une dose de trinitrine en urgence qui fait cesser la crise. Une sonde urinaire est placée. Le lendemain on note une diurèse à 555 cc.\",\n       \"text\": \"Dans le processus d'installation de l'ascite chez votre patient, on peut observer certains mécanismes physiologiques : épanchement, transsudation, exsudat. Identifiez ces termes en les associant à leurs définitions : 1- Épanchement ; 2- Transsudat ; 3Exsudat. a) suintement d'un liquide séro-fibrineux à travers une muqueuse enflammée ; b) suintement d'un liquide au niveau d'une surface non enflammée et obéissant seulement à des lois mécaniques, résultant d'un déséquilibre entre pression hydrostatique et pression oncotique ; c) présence de liquide ou de gaz dans une partie du corps qui n'en renferme pas. Cochez la bonne combinaison :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1-a) (2-b) (3-c)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(1-a) (2-b) (3-c)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1-c) (2-a) (3-b)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. (1-c) (2-a) (3-b)\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Épanchement = présence de liquide ou de gaz dans une cavité qui n'en contient pas (c). Exsudat = liquide séro-fibrineux suintant d'une surface enflammée (a). Transsudat = liquide passé à travers une surface non enflammée par simple déséquilibre des pressions hydrostatique/oncotique (b). La bonne combinaison est 1-c, 2-b, 3-a. Remarque : Les options A et B sont identiques dans le sujet.\\n\\nSource : Cours de médecine IDE 2 (INFAS, actualisé 2020), Pneumonie (formation d'exsudat) et Cirrhose (ascite = transsudat)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous devez injecter chez un patient de 58 kg, hémorragique, 5 mg/kg d'héparine. Vous disposez d'un flacon de 10 ml contenant 5 000 UI d'héparine. Quelle est la quantité en ml d'héparine injectez-vous, sachant que 1 mg d'héparine = 100 UI ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A- 2,90 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B- 5,80 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C- 11,60 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D- 12,70 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C- 11,60 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dose = 58 kg × 5 mg/kg = 290 mg = 29 000 UI ; flacon = 5 000 UI / 10 ml = 500 UI/ml → 29 000 / 500 = 58 ml.\\n\\nSource : Calcul de dose (1 mg = 100 UI)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En plaçant une perfusion de 500 ml de SG 10 % au malade, quelle est la quantité de matière en grammes (g) de glucose administrée au total au patient à l'issue de la perfusion ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A- 75 g\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B- 50 g\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"D- 25 g\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"E- 12,5 g\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B- 50 g\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"SG 10 % = 10 g de glucose pour 100 ml → 500 ml contiennent 50 g. Remarque : Dans le sujet, les options sautent de B à D (pas d'option C).\\n\\nSource : Calcul de concentration\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour soulager les crises du patient, le médecin prescrit 35 mg de Risordan® en comprimé. Vous disposez de comprimés de 20 mg. Déterminer la quantité de comprimés à préparer afin de satisfaire la prescription\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A- 1 cp\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B- 1 cp + ½ cp\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C- 1 cp + 2/3 cp\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D- 1 cp + 3/4 cp\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D- 1 cp + 3/4 cp\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"35 mg / 20 mg = 1,75 comprimé = 1 cp + 3/4 cp.\\n\\nSource : Calcul de dose Voici un extrait du Serment de Florence Nightingale (FN), fondement du serment dit par les infirmières et infirmiers dans de nombreux pays : « … Je m'abstiendrai de toute pratique délictueuse ou malfaisante. Je ne prendrai ou n'administrerai volontairement aucun remède dangereux. J'aiderai de mon mieux le médecin dans son travail, et je me dévouerai au bien-être de ceux qui sont laissés à ma garde. »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la relation d'aide, le Serment de FN laisse entrevoir que : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A La profession infirmière est subalterne de celle du médecin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B La profession infirmière est collaboratrice de celle du médecin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C La profession infirmière est indépendante de celle du médecin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B La profession infirmière est collaboratrice de celle du médecin\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"« J'aiderai de mon mieux le médecin dans son travail » : le serment présente l'infirmière comme collaboratrice du médecin, ni subalterne ni indépendante.\\n\\nSource : (explication hors cours du projet ; extrait du serment cité dans le sujet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le dévouement de l'infirmière au bien-être de ceux qui sont laissés à sa garde engage l'infirmière à une obligation de : cochez la bonne proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A résultat\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B moyen\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B moyen\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le soignant s'engage à mettre en œuvre tous les moyens pour le bien-être du patient, sans pouvoir garantir la guérison : c'est une obligation de moyens.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le dévouement de l'infirmière au bien-être de ceux qui sont laissés à sa garde invite l'infirmière à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A un accueil et une prise en charge intéressés du patient\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B un accueil et une prise en charge désintéressés du patient\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B un accueil et une prise en charge désintéressés du patient\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le dévouement implique un accueil et une prise en charge désintéressés : soigner sans attendre de contrepartie personnelle.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-med-j7-ide3__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, une correspond à la formulation correcte d'un diagnostic infirmier de l'affection du patient :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A Syndrome douloureux thoracique relié à une perturbation du débit sanguin coronaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B Perturbation du débit sanguin coronaire reliée au syndrome douloureux thoracique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C Aucune des deux propositions n'est correcte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. A Syndrome douloureux thoracique relié à une perturbation du débit sanguin coronaire\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un diagnostic infirmier s'énonce « problème (manifestation) relié à sa cause » : ici, le syndrome douloureux thoracique est relié à la perturbation du débit sanguin coronaire.\\n\\nSource : Documents de révision L3 Médecine, Soins infirmiers (énoncé du diagnostic infirmier : problème + étiologie) (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Médecine · Prépa D.E J7 (IDE3)\",\n       \"sourceFile\": \"J7_Medecine_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
